fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Calculate the difference
    let diff = a.wrapping_sub(b);
    
    // Check if diff is strictly between -tol and tol
    // Since tol is strictly positive, -tol is negative
    diff > -tol && diff < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // The problem states arrays have equal, non-zero length
    // and tol is strictly positive, so we don't need to check those
    
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both arrays simultaneously
    for (a_val, b_val) in a.iter().zip(b.iter()) {
        result.push(is_close_i8(*a_val, *b_val, tol));
    }
    
    result
}